contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        uint256 bT_before = c._BASE_TARGET_();
        uint256 qT_before = c._QUOTE_TARGET_();
        uint256 bR_before = c._BASE_RESERVE_();
        uint256 qR_before = c._QUOTE_RESERVE_();
        uint256 r_before = c._RState_();

        c.correctRState();

        uint256 bT_after = c._BASE_TARGET_();
        uint256 qT_after = c._QUOTE_TARGET_();
        uint256 bR_after = c._BASE_RESERVE_();
        uint256 qR_after = c._QUOTE_RESERVE_();
        uint256 r_after = c._RState_();

        // _RState_ enum: 0=ONE, 1=ABOVE_ONE, 2=BELOW_ONE
        bool targetValid;
        if (r_before == 1) {
            // ABOVE_ONE is only bypassed when quote reserve < quote target;
            // if it fixes the state it must reset targets to current reserves.
            targetValid = r_after == 1
                ? qT_after <= qR_after
                : (bT_after == bR_after && qT_after == qR_after && r_after == 0);
        } else if (r_before == 2) {
            // BELOW_ONE is only bypassed when base reserve < base target;
            // otherwise targets cannot change.
            targetValid = bT_after == bT_before && qT_after == qT_before && r_after == r_before;
        } else {
            targetValid = bT_after == bT_before && qT_after == qT_before && r_after == r_before;
        }

        assert(targetValid);
    }
}

