contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 amount) public payable {
        require(to != address(0), "recipient must be nonzero");
        require(to != address(this), "recipient must differ from sender");

        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(to);

        require(amount <= senderBefore, "amount must not exceed sender balance");

        c.transfer(to, amount);

        uint256 senderAfter = c.balanceOf(address(this));
        uint256 recipientAfter = c.balanceOf(to);

        assert(senderAfter + recipientAfter == senderBefore + recipientBefore);
    }
}
